import json

with open('task.json') as f:
    task = json.load(f)

parts = task['parts']

# For each part, determine what supports it (what's directly below)
# A part is supported by any part whose top surface overlaps with this part's bottom footprint
# and whose top z == this part's bottom z

def get_footprint(p):
    sx, sy, sz = p['size_m']
    tx, ty, tz = p['target_position']
    return {
        'x_min': tx - sx/2, 'x_max': tx + sx/2,
        'y_min': ty - sy/2, 'y_max': ty + sy/2,
        'z_bot': tz - sz/2, 'z_top': tz + sz/2
    }

def overlaps(fp1, fp2):
    """Check if fp1's x-y footprint overlaps fp2's x-y footprint"""
    x_overlap = max(fp1['x_min'], fp2['x_min']) < min(fp1['x_max'], fp2['x_max'])
    y_overlap = max(fp1['y_min'], fp2['y_min']) < min(fp1['y_max'], fp2['y_max'])
    return x_overlap and y_overlap

fps = {}
for p in parts:
    fps[p['index']] = get_footprint(p)

TOL = 0.001  # 1mm tolerance for z matching

print("Part -> Supported by:")
deps = {}
for p in parts:
    idx = p['index']
    fp = fps[idx]
    supporters = []
    for q in parts:
        qidx = q['index']
        if qidx == idx:
            continue
        qfp = fps[qidx]
        # q's top must match idx's bottom, and footprints must overlap
        if abs(qfp['z_top'] - fp['z_bot']) < TOL and overlaps(fp, qfp):
            supporters.append(qidx)
    deps[idx] = supporters
    print(f"  Part {idx:2d}: supported by {supporters}")

# Build order: topological sort
import heapq
in_degree = {i: len(deps[i]) for i in deps}
dependents = {i: [] for i in deps}
for i, s in deps.items():
    for d in s:
        dependents[d].append(i)

# Start with parts that have no deps
available = [i for i in deps if in_degree[i] == 0]
build_order = []
while available:
    available.sort()
    node = available.pop(0)
    build_order.append(node)
    for dep in dependents[node]:
        in_degree[dep] -= 1
        if in_degree[dep] == 0:
            available.append(dep)

print(f"\nBuild order ({len(build_order)} parts):")
print(build_order)

